; Generated by tools/disasm.py (the line comment format is described in src/main.asm).

NMI:                              ; watchdog first: interrupted PC outside ROM, B/D flag set, stack < $30, NMI re-entered
  PHA                             ;C--S 03DC1 FDB1: 48
  TXA                             ;C--- 03DC2 FDB2: 8A
  PHA                             ;C--- 03DC3 FDB3: 48
  TYA                             ;C--- 03DC4 FDB4: 98
  PHA                             ;C--- 03DC5 FDB5: 48
  TSX                             ;C--- 03DC6 FDB6: BA
  CPX #NMI_STACK_MIN              ;C--- 03DC7 FDB7: E0 30
  BCC NmiWatchdogReset            ;C--- 03DC9 FDB9: 90 19
; stack reads after TSX: $0104,X = pushed P (B/D bits), $0106,X = high byte of the interrupted PC
  LDA frameCounter+2,X            ;C--- 03DCB FDBB: BD 04 01
  AND #P_FLAG_B|P_FLAG_D          ;C--- 03DCE FDBE: 29 18
  BNE NmiWatchdogReset            ;C--- 03DD0 FDC0: D0 12
  LDA resetSignature+1,X          ;C--- 03DD2 FDC2: BD 06 01
  CMP #>PRG_START                 ;C--- 03DD5 FDC5: C9 E0
  BCC NmiWatchdogReset            ;C--- 03DD7 FDC7: 90 0B
  LDA resetCounter                ;C--- 03DD9 FDC9: AD 15 01
  CMP #RESETS_AB_TRICK            ;C--- 03DDC FDCC: C9 2D
  BEQ NmiWatchdogReset            ;C--- 03DDE FDCE: F0 04
  LDA nmiBusy                     ;C--- 03DE0 FDD0: A5 2A
  BEQ NmiMain                     ;C--- 03DE2 FDD2: F0 26
NmiWatchdogReset:                 ; A+B on controller 2: warm reset (keeps the signature), else cold reset
  JSR ReadControllers             ;T--- 03DE4 FDD4: 20 6E F4
  LDA joy2                        ;T--- 03DE7 FDD7: A5 F1
  AND #BTN_A|BTN_B                ;T--- 03DE9 FDD9: 29 C0
  CMP #BTN_A|BTN_B                ;T--- 03DEB FDDB: C9 C0
  BNE ResetCold                   ;T--- 03DED FDDD: D0 13
ResetKeepSignature:               ; write the signature back to $0105 and restart through the RESET vector.
  LDA #$00                        ;T--- 03DEF FDDF: A9 00
  STA musicPlayerFlag             ;T--- 03DF1 FDE1: 8D 01 01
  LDX #SIGNATURE_LEN-1            ;T--- 03DF4 FDE4: A2 0F
@loop:
  LDA ResetSignature,X            ;T--- 03DF6 FDE6: BD B5 FB
  STA resetSignature,X            ;T--- 03DF9 FDE9: 9D 05 01
  DEX                             ;T--- 03DFC FDEC: CA
  BPL @loop                       ;T--- 03DFD FDED: 10 F7
  JMP (ResetVector)               ;T--- 03DFF FDEF: 6C FC FF
ResetCold:                        ; destroy the signature and restart through the RESET vector
  LDA #$00                        ;T--- 03E02 FDF2: A9 00
  STA resetSignature              ;T--- 03E04 FDF4: 8D 05 01
  JMP (ResetVector)               ;T--- 03E07 FDF7: 6C FC FF
NmiMain:                          ; nmiBusy++; MusicPlayer instead of the game when musicPlayerFlag is set
  INC nmiBusy                     ;C-J- 03E0A FDFA: E6 2A
  LDA musicPlayerFlag             ;C--- 03E0C FDFC: AD 01 01
  BEQ NmiRender                   ;C--- 03E0F FDFF: F0 1B
  LDA #PPUMASK_ON                 ;T--- 03E11 FE01: A9 1E
  STA PPUMASK                     ;T--- 03E13 FE03: 8D 01 20
  LDA #$00                        ;T--- 03E16 FE06: A9 00
  STA OAMDMA                      ;T--- 03E18 FE08: 8D 14 40
  JSR MusicPlayer                 ;T--- 03E1B FE0B: 20 89 F2
  LDA PPUSTATUS                   ;T--- 03E1E FE0E: AD 02 20
  LDA #$00                        ;T--- 03E21 FE11: A9 00
